def crc16(text):
    crc = 0xFFFF
    for ch in text:
        crc ^= ord(ch) << 8
        for _ in range(8):
            crc = ((crc << 1) ^ 0x1021) if crc & 0x8000 else (crc << 1)
            crc &= 0xFFFF
    return crc

def forward(dev, seq, payload):
    line = "{},{},{}".format(dev, seq, payload)
    return "${:03d}{}*{:04X}".format(len(line), line, crc16(line))

