class Counter:
    def __init__(self, load, save, block=100):
        self.load, self.save, self.block = load, save, block
        self.next = self.limit = load()
    def take(self):
        if self.next >= self.limit:
            self.limit = self.next + self.block
            self.save(self.limit)
        self.next += 1
        return self.next
